              if (fdr.success) {
                process.stdout.write('Deleted: ' + name + '\n');
              } else {
                process.stdout.write('Error: ' + fdr.error + '\n');
              }
          } else {
            if (!arg) { process.stdout.write('Usage: delete <name>\n'); break; }
