              delete drives[dn];
              process.stdout.write('Drive "' + dn + '" deleted.\n');
            }
          }
          break;

        case 'help':
          process.stdout.write(
            'Server console commands:\n' +
            '  drives               - List all drives\n' +
            '  delete <name>        - Delete a drive (no drive mounted) or a file (drive mounted)\n' +
